using System.Runtime.CompilerServices;namespace Challenge;public record Row(string Id,string Name);public static class Exporter{static string Csv(string x){if(x.IndexOfAny([',',(char)34,'\n','\r'])<0)return x;var q=((char)34).ToString();return q+x.Replace(q,q+q)+q;}public static async IAsyncEnumerable<string> Export(IAsyncEnumerable<Row> source,[EnumeratorCancellation]CancellationToken ct=default){await foreach(var x in source.WithCancellation(ct)){ct.ThrowIfCancellationRequested();yield return $"{Csv(x.Id)},{Csv(x.Name)}";}}}
